-- Rewear Nordic: cleaned data for MySQL
-- Run the whole file in MySQL Workbench (File > Run SQL Script, or paste and press the lightning bolt).
-- Tables hold the same cleaned data as the Power BI model. 'Condition' is renamed Item_Condition and 'Returns' is renamed product_returns because those are reserved words in MySQL.

DROP DATABASE IF EXISTS rewear_nordic;
CREATE DATABASE rewear_nordic CHARACTER SET utf8mb4;
USE rewear_nordic;
SET NAMES utf8mb4;

CREATE TABLE warehouses (
  Warehouse_ID VARCHAR(10) NOT NULL,
  Warehouse_Name VARCHAR(100),
  City VARCHAR(50),
  Daily_Order_Capacity INT,
  PRIMARY KEY (Warehouse_ID)
);

CREATE TABLE customers (
  Customer_ID VARCHAR(10) NOT NULL,
  Registered_Date DATE,
  Region VARCHAR(50),
  Acquisition_Channel VARCHAR(50),
  Membership VARCHAR(20),
  PRIMARY KEY (Customer_ID)
);

CREATE TABLE products (
  Product_ID VARCHAR(10) NOT NULL,
  Warehouse_ID VARCHAR(10),
  Category VARCHAR(30),
  Item_Type VARCHAR(50),
  Brand_Tier VARCHAR(20),
  Item_Condition VARCHAR(20),
  Size VARCHAR(20),
  Listed_Date DATE,
  List_Price_SEK DECIMAL(10,2),
  PRIMARY KEY (Product_ID)
);

CREATE TABLE orders (
  Order_ID VARCHAR(12) NOT NULL,
  Customer_ID VARCHAR(10),
  Order_Timestamp DATETIME,
  Sales_Channel VARCHAR(20),
  Payment_Method VARCHAR(20),
  Order_Status VARCHAR(30),
  Delivery_Service VARCHAR(20),
  Delivery_Fee_SEK DECIMAL(8,2),
  Delivery_Fee_Refund_SEK DECIMAL(8,2),
  PRIMARY KEY (Order_ID)
);

CREATE TABLE order_items (
  Order_Item_ID VARCHAR(12) NOT NULL,
  Order_ID VARCHAR(12),
  Product_ID VARCHAR(10),
  Quantity INT,
  Sale_Price_SEK DECIMAL(10,2),
  Seller_Entitlement_SEK DECIMAL(10,2),
  Entitlement_Flag VARCHAR(10),
  PRIMARY KEY (Order_Item_ID)
);

CREATE TABLE fulfilment (
  Fulfilment_ID VARCHAR(12) NOT NULL,
  Order_ID VARCHAR(12),
  Warehouse_ID VARCHAR(10),
  Carrier VARCHAR(20),
  Fulfilment_Status VARCHAR(30),
  Promised_Dispatch_At DATETIME(3),
  Pick_Started_At DATETIME(3),
  Pack_Completed_At DATETIME(3),
  Dispatched_At DATETIME(3),
  Promised_Delivery_At DATETIME(3),
  Delivered_At DATETIME(3),
  Handling_Cost_SEK DECIMAL(8,2),
  Packaging_Cost_SEK DECIMAL(8,2),
  Carrier_Cost_SEK DECIMAL(8,2),
  Handling_Flag VARCHAR(10),
  Chronology_Flag VARCHAR(10),
  PRIMARY KEY (Fulfilment_ID)
);

CREATE TABLE product_returns (
  Return_ID VARCHAR(12) NOT NULL,
  Order_Item_ID VARCHAR(12),
  Requested_At DATETIME,
  Received_At DATETIME,
  Processed_At DATETIME,
  Return_Reason VARCHAR(40),
  Return_Status VARCHAR(30),
  Refund_Amount_SEK DECIMAL(10,2),
  Return_Handling_Cost_SEK DECIMAL(8,2),
  Return_Carrier_Cost_SEK DECIMAL(8,2),
  Chronology_Flag VARCHAR(10),
  PRIMARY KEY (Return_ID)
);

CREATE INDEX idx_oi_order ON order_items(Order_ID);
CREATE INDEX idx_oi_product ON order_items(Product_ID);
CREATE INDEX idx_ful_order ON fulfilment(Order_ID);
CREATE INDEX idx_ret_item ON product_returns(Order_Item_ID);
CREATE INDEX idx_ord_cust ON orders(Customer_ID);








-- Row-count check (expected: customers 2200, warehouses 2, products 9115, orders 4975, order_items 9115, fulfilment 4975, product_returns 1084)
SELECT 'customers' AS tbl, COUNT(*) AS n FROM customers
UNION ALL SELECT 'warehouses', COUNT(*) FROM warehouses
UNION ALL SELECT 'products', COUNT(*) FROM products
UNION ALL SELECT 'orders', COUNT(*) FROM orders
UNION ALL SELECT 'order_items', COUNT(*) FROM order_items
UNION ALL SELECT 'fulfilment', COUNT(*) FROM fulfilment
UNION ALL SELECT 'product_returns', COUNT(*) FROM product_returns;
